package com.tarikul.cs15ip

import android.graphics.Bitmap
import android.graphics.BitmapFactory
import android.util.Base64

/** Product photo of the Sony ICF-CS15iP, embedded so the app works fully offline. */
object MachineImage {
    private const val P0 = ""
    private const val P1 = ""

    fun bitmap(): Bitmap {
        val bytes = Base64.decode(P0 + P1, Base64.DEFAULT)
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    }
}